// The list is always the connection's own: the user is the session's, never a field the frame could name.
async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  try {
    const summaries =
      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
    sendSessionList(ws, summaries.map(toSummaryFrame));
  } catch (error) {
    // The log names the session and the failure, and nothing of what the store was asked for or answered.
    log.error('ws', 'conversation list failed', {
      sessionId: session.sessionId,
      userId: session.userId,
      error: messageOf(error),
    });
    throw error;
  }
}

// A store answers Dates; the wire carries ISO strings, which is what JSON would have made of them anyway.
const toSummaryFrame = (summary: SessionSummary): SessionSummaryFrame => ({
  sessionId: summary.sessionId,
  createdAt: new Date(summary.createdAt).toISOString(),
  updatedAt: new Date(summary.updatedAt).toISOString(),
  entryCount: summary.entryCount,
});

